<template>
    <!-- 装饰性背景元素 -->
    <view class="bg-decoration bg-decoration-1"></view>
    <view class="bg-decoration bg-decoration-2"></view>
    <view class="bg-decoration bg-decoration-3"></view>
    
    <!-- 登录容器 -->
    <view class="login-container">
      <view class="logo-section">
        <view class="logo">SZTU</view>
        <text class="title">欢迎使用深圳技术大学</text>
        <text class="title-sub">校园小程序</text>
      </view>
      <!-- 登录表单 -->
      <cover-view class="{{isInputing?'hint':'disappear'}}">
        <cover-view  class="hint-item" wx:for="{{filterUsrIds}}" wx:key="index" data-value="{{item}}" bindtap="selectHint">
            {{item}}
        </cover-view>
      </cover-view>
      <form bindsubmit="formSubmit" class="form-base">
        <view class="form-group">
          <label class="form-label" focus="{{true}}">学号</label>
          <view class="input-wrapper">
            <input type="text" placeholder="请输入学号" value="{{userInfo.userId}}" bindinput="onUsrIdInput"  bindfocus="onUsrIdFocus" bindblur="onUsrIdBlur" required />
          </view>
        </view>
        <view class="form-group">
          <label class="form-label">验证码</label>
          <view class="input-wrapper">
            <input type="number" placeholder="请输入验证码" value="{{userInfo.code}}" bindinput="onCodeInput" required />
            <button type="primary" bind:tap="onSendSmsCode" disabled="{{isLogining}}">
              <!-- 倒计时显示 -->
              <block wx:if="{{countdown > 0}}">
                重新发送({{countdown}}s)
              </block>
              <block wx:else>
                {{isSending ? '发送中...' : '发送验证码'}}
              </block>
            </button>
          </view>
        </view>
        <view class="remember-forgot">
          <view class="remember-me">
            <checkbox-group bindchange="onRememberChange">
              <checkbox value="remAc" />
              <label class="remember-label">记忆账号</label>
            </checkbox-group>
          </view>
          <text class="forgot-password" bindtap="forgotPassword">忘记密码？</text>
        </view>
        <button form-type="submit" class="login-button" bindtap="onTapSubmit" loading="{{isLogining}}">登录</button>
      </form>
    </view>
    
    <!-- 二次人工验证 -->
    <view class="login-container disappear">
      <view class="logo-section">
        <view class="logo">SZTU</view>
        <text class="title">欢迎使用深圳技术大学</text>
        <text class="title-sub">校园小程序</text>
      </view>
      <view class="form-group">
          <label class="form-label">二次验证码</label>
          <view class="input-wrapper">
            <input type="number" placeholder="请输入二次验证码" value="{{}}" bindinput="" required />
            <image src="" mode="scaleToFill"/>
          </view>
        </view>
    </view>
</template>

<script>
    // const { smsUrl, loginUrl } = require("../../components/login/utils");
    // import { IUserInfo } from '../../types/userInfo';
    
    // 获取全局 app
    const app = getApp()
    
    Page({
      data: {
        userInfo: {
          userId: null,
          code: null
        },
        cookies: [],
        originalUsrIds: [],
        filterUsrIds: [],
        rememberAcc: false,
        isInputing: false,
        isSending: false,
        isLogining: false,
        countdownTimer: null,
        countdown: 0
      },
      onLoad(options) {
        // 如果要登录，也即尝试自动登录失败了
        this.setData({
          userInfo: {
            userId: null,
            code: null
          },
          cookies: [],
          originalUsrIds: [],
          filterUsrIds: [],
          rememberAcc: false,
          isInputing: false,
          isSending: false,
          countdown: 0
        });
        const usrIds = wx.getStorageSync('usrIds') || [];
        if (usrIds.length > 0) {
          // 本地有历史 usrIds 存在
          this.setData({
            originalUsrIds: usrIds
          });
        }
        const localCookies = wx.getStorageSync('cookies') || [];
        if (localCookies.length > 0) {
          // 本地有历史 cookies 存在，可尝试直接登录，无需密码
          this.setData({
            cookies: localCookies
          });
          wx.request({
            url: getApp().globalData.baseURL + cookieLoginUrl, // 接口地址
            method: 'POST',
            header: {
              'Content-Type': 'application/json'
            },
            data: {
              cookies,
            },
            success: (res) => {
              console.log('登录接口返回：', res.data);
              if (res.statusCode === 200) {
                wx.showToast({
                  title: '登录成功',
                  icon: 'success',
                  duration: 2000
                });
                setTimeout(() => {
                  // 延时跳转到首页，首页是tab页
                  wx.switchTab({ url: '/pages/home/index' });
                }, 2000);
                // 持久化储存
                if (rememberAcc) {
                  newArrays = wx.getStorageSync('usrIds');
                  newArrays.push(this.data.userInfo.userId);
                  newArrays = setFunction(newArrays);
                  wx.setStorageSync('usrIds', {
                    acceptedArrays: newArrays
                  });
                  console.log("已进行本地持久化储存");
                }
                updateDataset(res.data);
              } else {
                wx.showToast({
                  title: res.data.msg || '登录失败，请检查账号密码',
                  icon: 'none',
                  duration: 2000
                });
              }
            },
            fail: (err) => {
              // 请求失败回调（网络错误、接口不可达等）
              console.error('登录请求失败：', err);
              wx.showToast({
                title: '登录时出现错误，请稍后重试',
                icon: 'none',
                duration: 2000
              });
            }
          });
        }
      },
      onUsrIdInput(e) {
        const inputV = e.detail.value?.trim() || '';
        this.setData({
          'userInfo.userId': inputV,
          isInputing: true
        });
        // 
      },
      onUsrIdFocus(e) {
        // 从data中取当前输入的userId  修复作用域问题
        // const query = this.createSelectorQuery();
        // console.log(query.selectAll('.hint'));
        // console.log(query.selectAll('.hint').fields({properties:true}));
        const inputV = e.detail.value?.trim() || '';
        // 展示提示
        if (inputV.length > 0) {
          const filterUsrIds = this.data.originalUsrIds.filter(ele => { return ele.startsWith(inputV); });
          if (filterUsrIds.length > 0) this.setData({ filterUsrIds });
        } else {
          this.setData({ filterUsrIds: this.data.originalUsrIds });
        }
      },
      onUsrIdBlur(e) {
        this.setData({
          isInputing: false
        });
      },
      onCodeInput(e) {
        const inputV = e.detail.value?.trim() || '';
        this.setData({
          'userInfo.code': inputV
        });
      },
    
      onSendSmsCode(e) {
        // 检查是否正在发送或倒计时中
        if (this.data.isSending || this.data.countdown > 0)
          return;
        if (this.data.userInfo.userId === null || this.data.userInfo.userId.length <= 0) {
          wx.showToast({ title: '请先输入工号', icon: 'none' });
          return;
        }
        // 防连击
        this.setData({ isSending: true });
        this.startCountdown(60);
    
        // 请求
        wx.request({
          url: getApp().globalData.baseURL + smsUrl, // 接口地址
          method: 'GET',
          header: {},
          data: {
            id: this.data.userInfo.userId,
          },
          success: (res) => {
            console.log('请求验证码接口返回：', res.data);
            if (res.statusCode === 200) {
              wx.showToast({
                title: '验证码已发送',
                icon: 'success',
                duration: 2000
              });
            }
            else {
              // 请求失败回调（网络错误、接口不可达等）
              wx.showToast({
                title: res.data.msg || '请求验证码异常，请检查账号密码',
                icon: 'error',
                duration: 2000
              });
            }
          },
          fail: (err) => {
            console.error('验证码请求失败：', err);
            wx.showToast({
              title: '网络异常，请稍后重试',
              icon: 'error',
              duration: 2000
            });
            // 重置发送状态
            this.resetCountdown();
          }
        });
    
      },
    
      // === 倒计时处理 ===
      startCountdown(seconds) {
        // 先清除可能存在的定时器
        this.clearCountdown();
        this.setData({ countdown: seconds });
        // 设置定时器
        const timer = setInterval(() => {
          const newCountdown = this.data.countdown - 1;
          if (newCountdown <= 0) {
            this.resetCountdown();
          } else {
            this.setData({ countdown: newCountdown });
          }
        }, 1000);
        this.setData({ countdownTimer: timer });
      },
    
      // === 重置倒计时 ===
      resetCountdown() {
        this.clearCountdown();
        this.setData({
          countdown: 0,
          isSending: false
        });
      },
    
      // === 倒计时终止 ===
      clearCountdown() {
        if (this.data.countdownTimer) {
          // 清除定时器
          clearInterval(this.data.countdownTimer);
          this.setData({ countdownTimer: null });
        }
      },
    
      // === 显示错误 ===
      showError(message) {
        this.setData({ errorMsg: message });
        setTimeout(() => {
          this.setData({ errorMsg: '' });
        }, 3000);
      },
    
      onTapSubmit(e) {
        if (!this.data.userInfo.userId) {
          wx.showToast({ title: '请输入学号', icon: 'none' });
          return;
        }
        if (!this.data.userInfo.code) {
          wx.showToast({ title: '请输入密码', icon: 'none' });
          return;
        }
        wx.showLoading({
          title: '登录中...',
          mask: true
        });
        this.setData({
          isLogining: true
        });
    
        // 发送POST请求
        wx.request({
          url: getApp().globalData.baseURL + loginUrl, // 接口地址
          method: 'POST',
          header: {
            'Content-Type': 'application/json'
          },
          timeout: 60000,
          data: {
    
            
            userId: this.data.userInfo.userId,
            code: this.data.userInfo.code,
            loginType: "SMS"
          },
          success: (res) => {
            console.log('登录接口返回：', res.data);
            if (res.statusCode === 200) {
              wx.showToast({
                title: '登录成功',
                icon: 'success',
                duration: 2000
              });
              setTimeout(() => {
                wx.switchTab({ url: '/pages/home/index' });
              }, 2000);
              // 持久化储存
              if (rememberAcc) {
                newArrays = wx.getStorageSync('usrIds');
                newArrays.push(this.data.userInfo.userId);
                newArrays = setFunction(newArrays);
                wx.setStorageSync('usrIds', {
                  acceptedArrays: newArrays
                });
                console.log("已进行本地持久化储存");
              }
              updateDataset(res.data);
            } else {
              wx.showToast({
                title: res.data.msg || '登录失败，请检查账号密码',
                icon: 'none',
                duration: 2000
              });
            }
          },
          // 请求失败回调（网络错误、接口不可达等）
          fail: (err) => {
            console.error('登录请求失败：', err);
            wx.showToast({
              title: '登录时出现错误，请稍后重试',
              icon: 'none',
              duration: 2000
            });
          }
        });
        this.setData({ isLogining: false });
      },
    
      // === 记忆勾与持久化储存 ===
      onRememberChange(e) {
        this.setData({
          rememberAcc: e.detail.value.length > 0
        });
      },
    
      updateDataset(resData) {
        const app = getApp();
        app.globalData.setData({
          cookies: this.data.cookies,
          userInfo: resData.userInfo,
          loginTimeStamp: Date.now(),
          isLoggedIn: true,
        });
      }
    });
</script>

<style>
    /* 页面根容器（唯一定义，消除重复） */
    page {
    	font-family: 'PingFang SC', 'Noto Sans SC', sans-serif;
    	min-height: 100vh;
    	/* background: linear-gradient(135deg, #667eea 0%, #764ba2 25%, #f093fb 50%, #4facfe 75%, #00f2fe 100%); */
    	/* background: linear-gradient(135deg,
    			#667eea 0%,
    			#764ba2 15%,
    			#f093fb 30%,
    			#ff6ec4 45%,
    			#ff8a00 60%,
          #4facfe 75%,
          #184cad 85%,
    			#00f2fe 90%,
    			#00ff7f 100%);
      animation: gradientFlow 15s ease infinite; */
    	/* background: linear-gradient(
            135deg,
            #ff0000 0%,    
            #ff7f00 14%,   
            #ffff00 28%,   
            #00ff00 42%,   
            #0000ff 56%,   
            #4b0082 70%,   
            #9400d3 84%,   
            #ff0000 100%   
        );
        animation: gradientFlow 10s ease infinite; */
    	/* background-size: 200% 200%; */
    	/* background: conic-gradient(
            from 0deg,
            #ff0000 0deg,     
            #ff7f00 51.4deg,  
            #ffff00 102.8deg, 
            #00ff00 154.2deg, 
            #0000ff 205.6deg, 
            #4b0082 257deg,   
            #9400d3 308.4deg, 
            #ff0000 360deg    
        );
      animation: rainbowRotate 3s linear infinite; */
    
    	/* background-size: 400% 400%; */
    	display: flex;
    	align-items: center;
    	justify-content: center;
    	padding: 20rpx 20rpx;
    	/* 进一步缩小左右内边距 */
    	position: relative;
    	box-sizing: border-box;
    	/* 关键：padding不占额外宽度 */
    }
    
    page::before {
    	content: '';
    	position: absolute;
    	top: 50%;
    	left: 50%;
    	width: 400vw;
    	height: 400vh;
    	background: conic-gradient(from 0deg,
    			rgba(255, 0, 0, 0.65) 0deg,
    			rgba(255, 127, 0, 0.65) 51.4deg,
    			rgba(255, 255, 0, 0.65) 102.8deg,
    			rgba(0, 255, 0, 0.65) 154.2deg,
    			rgba(7, 7, 255, 0.65) 205.6deg,
    			rgba(75, 0, 130, 0.65) 257deg,
    			rgba(148, 0, 211, 0.65) 308.4deg,
    			rgba(255, 0, 0, 0.65) 360deg);
    	transform-origin: center center;
    	transform: translate(-50%, -50%);
    	animation: rainbowRotate 8s linear infinite;
    	z-index: -1;
    }
    
    .disappear {
    	display: none;
    }
    
    /* 渐变动画 */
    @keyframes gradientFlow {
    	0% {
    		background-position: 0% 50%;
    	}
    
    	50% {
    		background-position: 100% 50%;
    	}
    
    	100% {
    		background-position: 0% 50%;
    	}
    }
    
    @keyframes rainbowRotate {
    	from {
    		transform: translate(-50%, -50%) rotate(0deg);
    	}
    
    	to {
    		transform: translate(-50%, -50%) rotate(360deg);
    	}
    }
    
    /* 装饰性背景元素：缩小尺寸，避免溢出屏幕 */
    .bg-decoration {
    	position: absolute;
    	border-radius: 50%;
    	opacity: 0.1;
    	animation: float 20s ease-in-out infinite;
    }
    
    .bg-decoration-1 {
    	width: 400rpx;
    	/* 原600rpx，大幅缩小 */
    	height: 400rpx;
    	background: radial-gradient(circle, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0) 70%);
    	top: -150rpx;
    	left: -150rpx;
    	animation-delay: 0s;
    }
    
    .bg-decoration-2 {
    	width: 300rpx;
    	/* 原400rpx */
    	height: 300rpx;
    	background: radial-gradient(circle, rgba(255, 255, 255, 0.6) 0%, rgba(255, 255, 255, 0) 70%);
    	bottom: -80rpx;
    	right: -80rpx;
    	animation-delay: 5s;
    }
    
    .bg-decoration-3 {
    	width: 200rpx;
    	/* 原300rpx */
    	height: 200rpx;
    	background: radial-gradient(circle, rgba(255, 255, 255, 0.7) 0%, rgba(255, 255, 255, 0) 70%);
    	top: 50%;
    	right: 5%;
    	animation-delay: 10s;
    }
    
    @keyframes float {
    
    	0%,
    	100% {
    		transform: translate(0, 0) scale(1);
    	}
    
    	33% {
    		transform: translate(40rpx, -40rpx) scale(1.1);
    	}
    
    	/* 缩小位移 */
    	66% {
    		transform: translate(-30rpx, 30rpx) scale(0.9);
    	}
    }
    
    /* 登录容器：适配iPhone 12/13 Pro（780rpx宽度）的核心调整 */
    .login-container {
    	background: rgba(255, 255, 255, 0.95);
    	backdrop-filter: blur(40rpx);
    	border-radius: 48rpx;
    	padding: 50rpx 30rpx;
    	/* 进一步缩小内边距 */
    	width: 90%;
    	/* 基于屏幕宽度的百分比 */
    	max-width: 650rpx;
    	/* 适配780rpx屏幕，留足边距 */
    	box-shadow: 0 30rpx 80rpx rgba(0, 0, 0, 0.12),
    		0 0 0 2rpx rgba(255, 255, 255, 0.3) inset;
    	animation: slideUp 0.6s ease-out;
    	position: relative;
    	box-sizing: border-box;
    	/* 关键：padding/border不占额外宽度 */
    }
    
    @keyframes slideUp {
    	from {
    		opacity: 0;
    		transform: translateY(60rpx);
    	}
    
    	to {
    		opacity: 1;
    		transform: translateY(0);
    	}
    }
    
    /* 顶部光晕：适配缩小后的容器 */
    .login-container::before {
    	content: '';
    	position: absolute;
    	top: 0;
    	left: 0;
    	right: 0;
    	height: 250rpx;
    	/* 原300rpx，进一步缩小 */
    	background: linear-gradient(180deg, rgba(102, 126, 234, 0.08) 0%, rgba(102, 126, 234, 0) 100%);
    	border-radius: 48rpx 48rpx 0 0;
    	pointer-events: none;
    }
    
    /* 校徽区域 */
    .logo-section {
    	text-align: center;
    	margin-bottom: 60rpx;
    	/* 原80rpx */
    	animation: fadeIn 0.8s ease-out 0.2s both;
    }
    
    @keyframes fadeIn {
    	from {
    		opacity: 0;
    		transform: translateY(-20rpx);
    	}
    
    	to {
    		opacity: 1;
    		transform: translateY(0);
    	}
    }
    
    /* logo：适配iPhone 12/13 Pro的尺寸 */
    .logo {
    	width: 130rpx;
    	/* 原100rpx */
    	height: 130rpx;
    	background: linear-gradient(135deg, #1e5bce 0%, #4a90e2 100%);
    	border-radius: 28rpx;
    	/* 原32rpx */
    	margin: 0 auto 25rpx;
    	/* 原30rpx */
    	display: flex;
    	align-items: center;
    	justify-content: center;
    	font-size: 50rpx;
    	/* 原56rpx */
    	color: white;
    	font-weight: 700;
    	box-shadow: 0 10rpx 30rpx rgba(30, 91, 206, 0.3);
    	/* transform-origin: center center; */
    	transform: rotate(-12deg);
    	transition: transform 0.3s ease;
    }
    
    .logo:active {
    	transform: rotate(15deg) scale(1.1);
    	/* animation: littleRotate 3s linear infinite; */
    }
    
    @keyframes littleRotate {
    	0% {
    		transform: rotate(10deg) scale(1.05);
    		background: linear-gradient(135deg, #1e5bce 0%, #4a90e2 100%);
    	}
    
    	25% {
    		transform: rotate(20deg) scale(1.05);
    		background: linear-gradient(135deg, #4a90e2 0%, #1e5bce 100%);
    	}
    
    	50% {
    		transform: rotate(40deg) scale(1.05);
    		background: linear-gradient(135deg, #4a90e2 0%, #1e5bce 100%);
    	}
    
    	75% {
    		transform: rotate(80deg) scale(1.05);
    		background: linear-gradient(135deg, #1e5bce 0%, #4a90e2 100%);
    	}
    
    	100% {
    		transform: rotate(100deg) scale(1.05);
    		background: linear-gradient(135deg, #1e5bce 0%, #4a90e2 100%);
    	}
    }
    
    /* 标题文字：进一步缩小 */
    .title,
    .title-sub {
    	font-size: 34rpx;
    	/* 原36rpx */
    	font-weight: 600;
    	color: #1a1a2e;
    	line-height: 1.3;
    	/* 缩小行高 */
    	letter-spacing: 0.4rpx;
    	display: block;
    }
    
    .title-sub {
    	margin-top: 5rpx;
    }
    
    /* 表单组 */
    .form-group {
    	margin-bottom: 30rpx;
    	/* 原36rpx */
    	animation: fadeIn 0.8s ease-out 0.4s both;
    }
    
    .form-group:nth-child(2) {
    	animation-delay: 0.5s;
    }
    
    /* 表单标签 */
    .form-label {
    	display: block;
    	margin-bottom: 14rpx;
    	/* 原16rpx */
    	font-size: 24rpx;
    	/* 原26rpx */
    	font-weight: 500;
    	color: #1a1a2e;
    	letter-spacing: 0.3rpx;
    }
    
    .input-wrapper {
    	display: flex;
    }
    
    .input-wrapper button {
    	padding: 10px;
    	margin-left: 20px;
    }
    
    /* 输入框：核心缩小，适配小屏 */
    input {
    	width: 100%;
    	padding: 10px;
    	height: 50px;
    	border: 3rpx solid transparent;
    	/* 原4rpx，缩小边框 */
    	background-color: white;
    	background: linear-gradient(white, white) padding-box,
    		linear-gradient(135deg, #e5e7eb 0%, #f3f4f6 100%) border-box;
    	border-radius: 28rpx;
    	/* 原32rpx */
    	font-size: 26rpx;
    	/* 原28rpx */
    	color: #1a1a2e;
    	outline: none;
    	transition: all 0.3s ease;
    	box-sizing: border-box;
    }
    
    input:focus {
    	border: 3rpx solid transparent;
